package oracle;
import java.util.*;import java.io.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;import core.game.node.entity.player.Player;import core.game.node.entity.npc.NPC;import core.game.world.map.Location;import core.net.packet.IoBuffer;
public class Support{
 static Map input;static Player player;static TreeMap<String,NPC>npcs;static List<Object>events,frames;static List<List<NPC>>views;static Map<String,Integer>calls;public static core.net.IoSession session;
 public static class Failure extends RuntimeException{}
 static int n(Object o){return((Number)o).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 static Location loc(Object o){if(o==null)return null;List a=(List)o;return Location.create(n(a.get(0)),n(a.get(1)),n(a.get(2)));}static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 static List names(List<NPC>ls){List out=new ArrayList();for(NPC n:ls)out.add(n==null?null:n.name);return out;}
 public static void emit(String event,Object...args){List row=new ArrayList();row.add(event);row.addAll(Arrays.asList(args));events.add(row);int count=calls.merge(event,1,Integer::sum);for(Object o:(List)input.getOrDefault("hooks",Collections.emptyList())){Map h=(Map)o;if(event.equals(h.get("event"))&&count==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}}
 public static void sent(byte[]bytes){List out=new ArrayList();for(byte x:bytes)out.add(x&255);frames.add(out);}
 public static void masks(NPC n,IoBuffer buffer,boolean sync){emit("masks",n.name,sync);Map cfg=(Map)((Map)input.get("npcs")).get(n.name);for(Object x:(List)cfg.getOrDefault("mask",Arrays.asList(0L)))buffer.put(((Number)x).byteValue());}
 public static List<NPC>candidates(Location l,int d){emit("candidates",coord(l),d);List<NPC>out=new ArrayList<>();for(Object name:(List)input.getOrDefault("candidates",Collections.emptyList()))out.add(name==null?null:npcs.get(name));return out;}
 static void set(NPC n,Map m){if(m.containsKey("index"))n.index=v(m,"index",0);if(m.containsKey("id"))n.id=v(m,"id",0);if(m.containsKey("location"))n.location=loc(m.get("location"));if(m.containsKey("hidden"))n.hidden=b(m,"hidden");if(m.containsKey("teleport"))n.properties.teleporting=b(m,"teleport");if(m.containsKey("direction"))n.direction.ordinal=v(m,"direction",0);if(m.containsKey("walk"))n.walkingQueue.walkDir=v(m,"walk",-1);if(m.containsKey("run"))n.walkingQueue.runDir=v(m,"run",-1);if(m.containsKey("required"))n.updateMasks.required=b(m,"required");if(m.containsKey("aggressive"))n.aggressiveHandler=b(m,"aggressive")?new NPC.Aggression(n):null;}
 static void act(Map a){String op=(String)a.get("op");NPC npc=npcs.get(a.getOrDefault("node","a"));List<NPC>list=player.renderInfo.localNPCs;switch(op){case"render":core.game.world.update.NPCRenderer.render(player);break;case"set":if("self".equals(a.get("node"))){Map f=(Map)a.get("fields");if(f.containsKey("index"))player.index=v(f,"index",1);if(f.containsKey("location"))player.location=loc(f.get("location"));}else set(npc,(Map)a.get("fields"));break;case"clear":list.clear();break;case"push":list.add(npc);break;case"erase":list.remove(v(a,"index",0));break;case"replaceList":player.renderInfo.localNPCs=new LinkedList<>();views.add(player.renderInfo.localNPCs);break;case"fail":throw new Failure();default:throw new AssertionError(op);}}
 static Map state(String error){Map out=new TreeMap();Map ns=new TreeMap();for(String name:npcs.keySet()){NPC n=npcs.get(name);Map values=new TreeMap();values.put("index",n.index);values.put("id",n.id);values.put("location",coord(n.location));values.put("walk",n.walkingQueue.walkDir);values.put("run",n.walkingQueue.runDir);values.put("required",n.updateMasks.required);values.put("hidden",n.hidden);values.put("teleport",n.properties.teleporting);values.put("direction",n.direction.ordinal);List tolerances=new ArrayList();if(n.aggressiveHandler!=null)for(Map.Entry<Integer,Integer>e:new TreeMap<Integer,Integer>(n.aggressiveHandler.playerTolerance).entrySet())tolerances.add(Arrays.asList(e.getKey(),e.getValue()));values.put("tolerance",n.aggressiveHandler==null?null:tolerances);ns.put(name,values);}out.put("npcs",ns);out.put("player",Arrays.asList(player.index,coord(player.location)));out.put("locals",names(player.renderInfo.localNPCs));List vs=new ArrayList();for(List<NPC>l:views)vs.add(names(l));out.put("views",vs);out.put("events",new ArrayList(events));out.put("frames",new ArrayList(frames));out.put("error",error);return out;}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);events=new ArrayList<>();frames=new ArrayList<>();calls=new HashMap<>();views=new ArrayList<>();npcs=new TreeMap<>();session=new core.net.IoSession();player=new Player();Map ps=(Map)input.getOrDefault("player",Collections.emptyMap());player.index=v(ps,"index",1);if(ps.containsKey("location"))player.location=loc(ps.get("location"));Map rows=(Map)input.get("npcs");for(Object name:rows.keySet()){NPC npc=new NPC((String)name);set(npc,(Map)rows.get(name));npcs.put((String)name,npc);}for(Object name:(List)input.getOrDefault("locals",Collections.emptyList()))player.renderInfo.localNPCs.add(name==null?null:npcs.get(name));views.add(player.renderInfo.localNPCs);List out=new ArrayList();for(Object a:(List)input.get("actions")){events.clear();frames.clear();String error=null;try{act((Map)a);}catch(Throwable e){error=e instanceof NullPointerException?"Null":e instanceof IndexOutOfBoundsException?"Index":e instanceof ConcurrentModificationException?"ConcurrentModification":e instanceof Failure?"Binding":e.getClass().getSimpleName();}out.add(state(error));}input.put("expected",out);System.out.println(JSONValue.toJSONString(input));}}}
}
